-- ============================================================================
-- Guia do Vendedor — seed de ANIMAIS (parte 1: categorias por espécie/sistema/fase)
--
-- MUDANÇA DE EIXO. O guia antigo só tinha RAÇA. O que dimensiona a venda é a
-- CRIAÇÃO: espécie + sistema + fase. Estes registros carregam consumo de
-- referência, perguntas para o vendedor, processo e equipamento; as raças
-- (parte 2) carregam identidade e perfil de cliente.
--
-- Consumo: os MESMOS números de CATEGORIAS em src/lib/venda-racao/catalogo.ts,
-- que já rodam em /producao-propria. Dois módulos com números diferentes foi
-- um dos achados da auditoria.
-- ============================================================================

on conflict (slug) do update set nome = excluded.nome, especie = excluded.especie, resumo = excluded.resumo, sinonimos = excluded.sinonimos, subgrupo = excluded.subgrupo, tipo = excluded.tipo, classificacao = excluded.classificacao, finalidade = excluded.finalidade, sistemas = excluded.sistemas, fases = excluded.fases, fase_estudo = excluded.fase_estudo, peso_min_kg = excluded.peso_min_kg, peso_max_kg = excluded.peso_max_kg, peso_nota = excluded.peso_nota, consumo_ref = excluded.consumo_ref, consumo_unidade = excluded.consumo_unidade, consumo_fatores = excluded.consumo_fatores, tipos_alimentacao = excluded.tipos_alimentacao, forma_fisica = excluded.forma_fisica, materias_comuns = excluded.materias_comuns, restricoes = excluded.restricoes, perguntas = excluded.perguntas, sinais_falta_info = excluded.sinais_falta_info, processo = excluded.processo, equipamentos = excluded.equipamentos, argumento = excluded.argumento, promessas_proibidas = excluded.promessas_proibidas, branorte = excluded.branorte, explicar_cliente = excluded.explicar_cliente, resumo_30s = excluded.resumo_30s, regiao = excluded.regiao, imagem_slug = excluded.imagem_slug, emoji = excluded.emoji, status = excluded.status, pendente_validacao = excluded.pendente_validacao, pendencias = excluded.pendencias, fontes = excluded.fontes, autor = excluded.autor, revisor_tecnico = excluded.revisor_tecnico, revisado_em = excluded.revisado_em, proxima_revisao = excluded.proxima_revisao, ordem = excluded.ordem;
