insert into public.guia_animais (slug, nome, especie, resumo, sinonimos, subgrupo, tipo, classificacao, finalidade, sistemas, fases, fase_estudo, peso_min_kg, peso_max_kg, peso_nota, consumo_ref, consumo_unidade, consumo_fatores, tipos_alimentacao, forma_fisica, materias_comuns, restricoes, perguntas, sinais_falta_info, processo, equipamentos, argumento, promessas_proibidas, branorte, explicar_cliente, resumo_30s, regiao, imagem_slug, emoji, status, pendente_validacao, pendencias, fontes, autor, revisor_tecnico, revisado_em, proxima_revisao, ordem) values
  ('bov-corte-cria', 'Corte — Cria (matriz com bezerro ao pé)', 'bovinos', 'Vaca de cria a pasto, com bezerro ao pé. O objetivo é desmamar bezerro pesado sem perder escore da matriz.', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"pasto"}'::text[], '{"cria"}'::text[], 'cria', null, null, null, '~5 kg/mês por matriz (≈165 g/dia) — sal mineral ou proteinado, não ração completa.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"sal mineral","proteinado"}'::text[], '{"farelada"}'::text[], '{"sal-mineral","sal-comum","fosfato-bicalcico","calcario-calcitico","ureia"}'::text[], '{"Formulação de mineral e de proteinado com ureia é de profissional habilitado."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'MISTURA SECA de produto mineral. Volume mensal baixo por animal, mas o rebanho costuma ser grande. Produto denso e corrosivo.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'O consumo por cabeça é pequeno, mas o rebanho de cria é grande e o consumo é o ano inteiro. Vale fazer a conta do gasto anual com mineral comprado pronto antes de descartar a produção própria.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Na cria o animal come pouco por cabeça, mas são muitas cabeças e é o ano todo. Produzir o próprio mineral só compensa a partir de um certo volume — é isso que o estudo mostra.', 'Matriz a pasto. Mineral/proteinado, ~5 kg/mês/cabeça. Produto denso e corrosivo: misturador horizontal e limpeza.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 10),
  ('bov-corte-recria', 'Corte — Recria', 'bovinos', 'Garrote e novilha ganhando peso a pasto com suplementação, entre a desmama e a engorda.', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"pasto","semiconfinamento"}'::text[], '{"recria"}'::text[], 'recria', null, null, null, '~60 kg/mês por animal (referência de ~0,67% do peso vivo).', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"proteinado","concentrado de recria"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","sal-mineral","nucleo-premix","ureia","farelo-algodao"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem de grão + mistura seca. Volume mensal já relevante: é onde a fábrica própria começa a fazer sentido.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Na recria o consumo por cabeça já é dez vezes o da cria. É a fase em que o produtor sente o custo do suplemento comprado.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Recria a pasto, ~60 kg/mês/cabeça. Moagem + mistura seca. Volume já justifica fábrica.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 20),
  ('bov-corte-mineral', 'Corte — Suplementação mineral a pasto', 'bovinos', 'Sal mineral no cocho o ano todo, corrigindo a deficiência do pasto brasileiro (principalmente fósforo).', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"pasto"}'::text[], '{"manutencao"}'::text[], 'manutencao', null, null, null, '~18 kg/mês por animal como suplemento de manutenção (≈0,15% do peso vivo). Mineral puro no cocho fica bem abaixo disso.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"sal mineral"}'::text[], '{"farelada"}'::text[], '{"sal-comum","fosfato-bicalcico","calcario-calcitico","nucleo-premix"}'::text[], '{"Formulação por profissional habilitado.","Sal e fosfato corroem o equipamento."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Mistura seca de produto MINERAL: denso, corrosivo e com microingredientes. Projeto diferente de quem só tritura milho.', '{"MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'Quem tem rebanho grande e compra mineral pronto o ano inteiro tem um gasto fixo alto e previsível — o cenário mais fácil de demonstrar no estudo.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O mineral é o que corrige o que falta no pasto. Produzir na propriedade é possível, mas é um projeto diferente: o mineral é pesado, é corrosivo e tem ingrediente que entra em grama.', 'Mineral de cocho o ano todo. Denso + corrosivo + microingrediente: horizontal, balança fina e limpeza.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 30),
  ('bov-corte-proteinado', 'Corte — Proteinado de seca', 'bovinos', 'Suplemento proteico de período seco, para segurar o desempenho quando o pasto perde qualidade.', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"pasto"}'::text[], '{"proteica"}'::text[], 'proteica', null, null, null, '~18 kg/mês por animal (referência de proteinado de seca).', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"proteinado"}'::text[], '{"farelada"}'::text[], '{"farelo-soja","farelo-algodao","milho","sal-comum","ureia","nucleo-premix"}'::text[], '{"Proteinado com ureia: ALTO RISCO se mal homogeneizado. Formulação e adaptação por profissional habilitado."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Mistura seca com proteico + mineral. Costuma levar UREIA — atenção redobrada à homogeneização.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'O proteinado é sazonal e concentrado na seca: o produtor sente o preço justamente quando o caixa está mais apertado.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Suplemento de seca, ~18 kg/mês. Costuma levar ureia: homogeneização é questão de segurança, não de qualidade.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","Presença e nível de ureia dependem de formulação profissional."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 40),
  ('bov-corte-semiconfinamento', 'Corte — Semiconfinamento', 'bovinos', 'Animal a pasto recebendo concentrado no cocho para acelerar o ganho sem confinar.', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"semiconfinamento"}'::text[], '{"semi_confinamento"}'::text[], 'semi_confinamento', null, null, null, '~120 kg/mês por animal (referência de ~1,0% do peso vivo em concentrado).', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"concentrado"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","farelo-algodao","nucleo-premix","sal-comum","ureia"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca em volume relevante. Cenário muito comum de venda da linha Compacta.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'É a faixa em que o volume mensal já paga a fábrica com folga e o cliente ainda tem o milho da própria safra.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'No semiconfinamento o senhor já move um volume grande de concentrado todo mês. É aí que moer o próprio milho e misturar aqui começa a fazer diferença de verdade na conta.', 'Concentrado no cocho a pasto, ~120 kg/mês/cabeça. Volume que justifica a fábrica com folga.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 50),
  ('bov-corte-confinamento', 'Corte — Confinamento', 'bovinos', 'Animal em cocho com dieta de alto concentrado até o abate. Maior consumo de ração por cabeça do rebanho de corte.', '{}'::text[], 'corte', 'categoria', null, 'corte', '{"confinamento"}'::text[], '{"confinamento","engorda"}'::text[], 'confinamento', null, null, null, '~297 kg/mês por animal de CONCENTRADO (referência de ~2,2% do peso vivo, base 450 kg). A dieta completa com volumoso é bem maior.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"concentrado","dieta completa (TMR)"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","caroco-algodao","nucleo-premix","calcario-calcitico","sal-comum","ureia","bicarbonato-sodio","casquinha-soja"}'::text[], '{"Silagem e volumosos NÃO entram na fábrica farelada.","Dieta de alto grão exige acompanhamento (risco de acidose)."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'ATENÇÃO À SEPARAÇÃO. A Branorte faz a MISTURA SECA (o concentrado). A dieta completa com silagem é trabalho de VAGÃO MISTURADOR, outro equipamento. Não confundir os dois na proposta.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA","PRE_LIMPEZA"}'::text[], 'Maior volume de concentrado por cabeça. Mas o argumento tem que ser preciso: a fábrica entrega o concentrado, não a dieta completa.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'No confinamento a nossa fábrica faz o concentrado — a parte seca. A silagem o senhor continua misturando no vagão ou entregando no cocho. Uma coisa não substitui a outra.', 'Maior consumo por cabeça (~297 kg/mês de concentrado). A fábrica faz a parte SECA; TMR é vagão misturador.', null, null, '🐂', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-gado-corte","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 60),
  ('bov-leite-bezerras', 'Leite — Bezerras (aleitamento e desaleitamento)', 'bovinos', 'Do nascimento ao desaleitamento. Fase curta, de consumo baixo, mas de ração cara e muito exigente.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"bezerreiro"}'::text[], '{"recria"}'::text[], 'recria', null, null, null, 'Consumo baixo por animal e crescente. Concentrado inicial de alta qualidade estimula o desenvolvimento do rúmen.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado inicial"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","quirera-arroz","calcario-calcitico"}'::text[], '{"Ração de bezerra tem exigência específica: formulação profissional."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Volume pequeno, exigência alta. Costuma ser mais barato COMPRAR pronto nesta fase — dizer isso é o que constrói confiança.', '{"MOINHO","MISTURADOR"}'::text[], 'Honestidade vende: em bezerreiro o volume raramente justifica produzir. Use a fase para mostrar que o estudo diz "não" quando é não.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Fase curta, ração cara, volume pequeno. Muitas vezes NÃO compensa produzir — e falar isso vale mais que forçar.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 70),
  ('bov-leite-novilhas', 'Leite — Novilhas (recria)', 'bovinos', 'Do desaleitamento à primeira cria. O objetivo é chegar ao peso e à idade de cobertura sem engordar demais.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"pasto","semiconfinamento"}'::text[], '{"recria"}'::text[], 'recria', null, null, null, '~60 kg/mês por animal (referência de recria).', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","farelo-trigo","sal-mineral","nucleo-premix"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ENSACADEIRA"}'::text[], 'A novilha é custo puro até parir. Reduzir o custo do concentrado dela é ganho direto.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Recria de reposição, ~60 kg/mês. Custo puro até parir — reduzir custo aqui é lucro direto.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 80),
  ('bov-leite-seca', 'Leite — Vacas secas', 'bovinos', 'Vaca no período seco, preparando a próxima lactação. Dieta controlada, sem excesso de energia.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"pasto","free_stall","compost_barn"}'::text[], '{"manutencao"}'::text[], 'manutencao', null, null, null, 'Consumo controlado, bem abaixo do de lactação. Pré-parto tem exigência mineral específica.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado de transição","sal mineral"}'::text[], '{"farelada"}'::text[], '{"farelo-trigo","milho","sal-mineral","nucleo-premix","calcario-calcitico"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Mistura seca. Fórmula diferente da de lactação: aumenta o número de fórmulas que a fábrica precisa rodar.', '{"MISTURADOR","CACAMBA_PESAGEM"}'::text[], 'Cada fórmula a mais reforça o valor de ter a fábrica na propriedade — trocar de fórmula é só trocar a receita, não trocar de fornecedor.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Dieta controlada de pré-parto. Fórmula própria: mais um motivo pra ter a fábrica em casa.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 90),
  ('bov-leite-lactacao-baixa', 'Leite — Lactação, baixa produção', 'bovinos', 'Vaca em lactação de menor volume, tipicamente a pasto. É a maior parte do rebanho leiteiro brasileiro.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"pasto"}'::text[], '{"gado_leite"}'::text[], 'gado_leite', null, null, null, 'Referência de ~120 kg/mês de concentrado. Vem da prática de ajustar o concentrado ao litro produzido — CONFIRMAR com o nutricionista.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado","sal mineral"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","farelo-trigo","sal-mineral","nucleo-premix","caroco-algodao"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca. O volumoso (pasto, silagem, cana) fica de fora da fábrica.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","ENSACADEIRA"}'::text[], 'É o maior número de propriedades do país. Ticket menor por cliente, mas volume de mercado enorme.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A vaca a pasto come menos concentrado, mas come todo dia, o ano inteiro. É a soma que pesa.', 'Maior fatia do leite nacional. ~120 kg/mês de concentrado. Volumoso fica fora da fábrica.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 100),
  ('bov-leite-lactacao-media', 'Leite — Lactação, média produção', 'bovinos', 'Vaca de produção intermediária, em pasto tecnificado ou semiconfinamento com dieta parcial.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"pasto","semiconfinamento","compost_barn"}'::text[], '{"gado_leite"}'::text[], 'gado_leite', null, null, null, 'Referência de ~210 kg/mês de concentrado. Derivado do ajuste ao litro — CONFIRMAR com o nutricionista.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado","dieta parcial (PMR)"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","caroco-algodao","farelo-trigo","nucleo-premix","calcario-calcitico","polpa-citrica"}'::text[], '{}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca em volume alto. Faixa de melhor retorno do estudo de viabilidade.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Volume diário garantido e previsível: o leite entra todo mês, então a economia aparece todo mês.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, '~210 kg/mês de concentrado, volume diário garantido. Costuma ser a melhor faixa de retorno.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 110),
  ('bov-leite-lactacao-alta', 'Leite — Lactação, alta produção', 'bovinos', 'Vaca de alta produção em confinamento (free stall ou compost barn), normalmente com dieta completa.', '{}'::text[], 'leite', 'categoria', null, 'leite', '{"free_stall","compost_barn","confinamento"}'::text[], '{"gado_leite"}'::text[], 'gado_leite', null, null, null, 'Referência de ~300 kg/mês ou mais de concentrado. Derivado do ajuste ao litro — CONFIRMAR com o nutricionista.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta","Nível de produção de leite","Estágio da lactação"}'::text[], '{"concentrado","dieta completa (TMR)"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","caroco-algodao","nucleo-premix","calcario-calcitico","bicarbonato-sodio","casquinha-soja","ddg-ddgs"}'::text[], '{"Dieta completa com silagem exige vagão misturador — outro equipamento.","Dieta de alto grão exige tamponamento e acompanhamento."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","Quantos litros por vaca por dia?","Quantas vacas em lactação hoje?","O sistema é pasto, compost barn ou free stall?","Fornece dieta parcial (concentrado no cocho) ou dieta completa?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'CUIDADO: quem trabalha com TMR já tem vagão misturador e pode achar que a fábrica substitui. NÃO substitui. A fábrica entrega o concentrado que ALIMENTA o vagão.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA","PRE_LIMPEZA"}'::text[], 'Maior consumo por vaca e cliente mais tecnificado — mas também o mais atento a custo por litro. Precisão nos números importa mais aqui do que em qualquer outro perfil.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O senhor já tem o vagão pra dieta completa. A nossa fábrica não substitui o vagão: ela faz o concentrado que entra nele, no lugar de o senhor comprar pronto.', 'Maior consumo por vaca. A fábrica ALIMENTA o vagão de TMR, não o substitui.', null, null, '🐄', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar.","A faixa por nível de produção deriva da prática de ajustar concentrado ao litro; precisa de validação do nutricionista antes de virar número fechado."}'::text[], '{"embrapa-gado-leite","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 120),
  ('sui-pre-inicial', 'Suínos — Pré-inicial (pós-desmame)', 'suinos', 'Leitão recém-desmamado. Consumo baixíssimo e ração muito cara e específica.', '{}'::text[], 'comercial', 'categoria', null, 'corte', '{"creche"}'::text[], '{"pre_inicial"}'::text[], 'pre_inicial', null, null, null, '~7 kg/mês por leitão.', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração pré-inicial"}'::text[], '{"farelada"}'::text[], '{"quirera-arroz","milho","farelo-soja","nucleo-premix","lisina"}'::text[], '{"Fórmula muito técnica, com ingredientes especiais. Formulação profissional obrigatória."}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Volume pequeno com exigência altíssima (produtos lácteos, plasma). Quase sempre é melhor COMPRAR pronta.', '{"MISTURADOR"}'::text[], 'Dizer que não compensa produzir a pré-inicial aumenta a credibilidade para as fases que compensam.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, 'Ração cara, volume mínimo. Normalmente NÃO compensa produzir. Falar isso constrói confiança.', null, null, '🐷', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 130),
  ('sui-inicial', 'Suínos — Inicial (creche)', 'suinos', 'Leitão na creche, após a pré-inicial. Consumo cresce rápido.', '{}'::text[], 'comercial', 'categoria', null, 'corte', '{"creche"}'::text[], '{"inicial"}'::text[], 'inicial', null, null, null, '~14 kg/mês por leitão.', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração inicial"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","lisina","quirera-arroz"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem FINA + mistura. Leitão exige granulometria mais fina que o suíno adulto.', '{"MOINHO","MISTURADOR","ACESSORIO","ENSACADEIRA"}'::text[], 'Granulometria é assunto de venda: peneira certa no moinho muda o aproveitamento da ração no leitão.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, '~14 kg/mês. Exige moagem FINA — peneira certa é parte da proposta.', null, null, '🐷', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 140),
  ('sui-crescimento', 'Suínos — Crescimento', 'suinos', 'Fase de crescimento, dos ~25 aos ~60 kg. Consumo já relevante.', '{}'::text[], 'comercial', 'categoria', null, 'corte', '{"comercial"}'::text[], '{"crescimento"}'::text[], 'crescimento', 25, 60, null, '~57 kg/mês por animal (≈1,9 kg/dia).', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração de crescimento"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","lisina"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura em volume alto. Junto com a terminação, é onde está o volume da granja.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Ração é o maior custo da suinocultura. Crescimento e terminação juntos concentram quase todo o consumo do ciclo.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, '~57 kg/mês/animal. Com a terminação, concentra o volume da granja.', null, null, '🐷', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 150),
  ('sui-terminacao', 'Suínos — Terminação', 'suinos', 'Fase final até o abate (~115–120 kg). Maior consumo diário do ciclo.', '{}'::text[], 'comercial', 'categoria', null, 'corte', '{"comercial"}'::text[], '{"terminacao"}'::text[], 'terminacao', 60, 120, null, '~90 kg/mês por animal (≈3,0 kg/dia).', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração de terminação"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","lisina","ddg-ddgs","farelo-arroz"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura no maior volume do ciclo. É aqui que a fábrica se paga.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'Maior volume por animal do ciclo. Se o cliente tem milho próprio, é o cenário mais forte do estudo.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Na terminação o porco come três quilos por dia. Multiplicado pelo lote, é caminhão de ração por mês. É onde a fábrica se paga mais rápido.', '~90 kg/mês/animal, maior volume do ciclo. Cenário mais forte do estudo.', null, null, '🐷', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 160),
  ('sui-gestacao', 'Suínos — Matriz em gestação', 'suinos', 'Porca gestante com consumo controlado, para não engordar demais antes do parto.', '{}'::text[], 'comercial', 'categoria', null, 'reprodução', '{"comercial"}'::text[], '{"gestacao"}'::text[], 'gestacao', null, null, null, '~75 kg/mês por matriz.', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração de gestação"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","lisina","farelo-trigo","casquinha-soja"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Mistura com bastante ingrediente fibroso (farelo de trigo) para dar saciedade sem energia. Fórmula VOLUMOSA: o misturador enche antes de bater o peso.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Fórmula de gestação é leve e volumosa — bom gancho para explicar por que o misturador é dimensionado por volume, não só por quilo.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, '~75 kg/mês. Fórmula leve e volumosa: dimensionar misturador por VOLUME.', null, null, '🐷', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 170),
  ('sui-lactacao', 'Suínos — Matriz em lactação', 'suinos', 'Porca amamentando. Pico de consumo do plantel reprodutor.', '{}'::text[], 'comercial', 'categoria', null, 'reprodução', '{"comercial"}'::text[], '{"lactacao"}'::text[], 'lactacao', null, null, null, '~165 kg/mês por matriz — o maior consumo do plantel.', 'kg de ração por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração de lactação"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","farelo-trigo","lisina"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura de ração de alta densidade energética.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Maior consumo do plantel reprodutor. Granjas de ciclo completo somam matriz + creche + terminação: o volume total surpreende o produtor.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equi