  ('ave-pre-postura', 'Poedeiras — Pré-postura', 'aves', 'Transição para a postura, com aumento de cálcio para preparar a formação de casca.', '{}'::text[], 'postura', 'categoria', null, 'ovos', '{"comercial"}'::text[], '{"pre_postura"}'::text[], 'pre_postura', null, null, null, '~2,7 kg/mês por ave.', 'kg de ração por ave por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração pré-postura"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","metionina","lisina","fitase-enzimas"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Mistura com aumento de calcário. Material denso: atenção à homogeneização.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM"}'::text[], 'Fase curta e específica — quem compra pronto costuma pular esta fórmula. Ter a fábrica permite fazê-la.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, null, '~2,7 kg/mês/ave. Sobe o cálcio: mistura densa, homogeneização importa.', null, null, '🥚', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 270),
  ('ave-postura', 'Poedeiras — Postura', 'aves', 'Fase produtiva da poedeira. Consumo estável e diário, o ano inteiro.', '{}'::text[], 'postura', 'categoria', null, 'ovos', '{"comercial"}'::text[], '{"postura"}'::text[], 'postura', null, null, null, '~3,4 kg/mês por ave na postura comercial (vermelha). Linhagem leve/branca fica em torno de ~3,0.', 'kg de ração por ave por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração de postura"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","nucleo-premix","calcario-calcitico","fosfato-bicalcico","sal-comum","metionina","lisina","fitase-enzimas","farelo-trigo"}'::text[], '{"Alto teor de calcário: material denso, risco de segregação em misturador vertical."}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura com ALTO teor de calcário (material denso, tende a segregar). Em poedeira, parte do calcário deve ficar GROSSO — não moer tudo fino.', '{"MOINHO","MISTURADOR","TRANSPORTADOR","SILO","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'Consumo diário, estável e o ano inteiro: é o perfil de demanda mais previsível de todos. Ótimo para o estudo de viabilidade.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A poedeira come todo dia, o ano inteiro, sem parar. É a conta mais fácil de fazer: o volume não oscila.', '~3,4 kg/mês/ave, demanda diária e estável. Muito calcário: cuidado com segregação.', null, null, '🥚', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 280),
  ('ave-caipira', 'Aves caipiras e coloniais', 'aves', 'Frango caipira e poedeira colonial, criados a campo, com ciclo mais longo e dieta menos densa.', '{}'::text[], 'caipira', 'categoria', null, 'dupla aptidão', '{"caipira","colonial","agroecologico"}'::text[], '{"caipira"}'::text[], 'caipira', null, null, null, '~3,0 kg/mês por ave no frango caipira (85–90 dias); poedeira colonial em torno de ~3,75.', 'kg de ração por ave por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"ração colonial","concentrado + milho próprio"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","concentrado-proteico","nucleo-premix","calcario-calcitico","farelo-trigo"}'::text[], '{}'::text[], '{"Quantos animais alojados?","Em qual fase — e quantas fases diferentes ele precisa atender?","Qual o consumo por dia ou por ciclo?","Quantos lotes por ano?","A ração é farelada ou peletizada hoje?","Que granulometria ele usa? (peneira do moinho)","Quantas fórmulas diferentes vai precisar produzir?","Com que frequência limpa o equipamento entre fórmulas?","Tem exigência de evitar contaminação cruzada (medicamento, ureia, mineral)?","A energia é monofásica ou trifásica?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem do milho próprio + mistura com concentrado. Cenário típico da agricultura familiar e da Compacta JR/01.', '{"MOINHO","MISTURADOR","ENSACADEIRA"}'::text[], 'Ticket menor, mas cliente fiel e recorrente. Muitas vezes já mistura na mão — a venda é sobre tempo e uniformidade.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'O caipira aceita uma ração mais simples e aproveita o milho da propriedade. É o encaixe mais direto da fábrica pequena.', 'Ciclo longo, dieta menos densa, milho próprio. Encaixe direto da Compacta JR/01.', null, null, '🐓', 'aprovado', true, '{"Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-suinos-aves","rostagno-tabelas","branorte-catalogo"}'::text[], 'Auditoria 2026-08-03', null, null, null, 290),
  ('ovinos', 'Ovinos (corte e leite)', 'ovinos', 'Ovinocultura de corte e de leite, em cria, recria e terminação. Demanda menor que bovinos, aves e suínos, mas real e compatível com ração farelada seca.', '{}'::text[], 'geral', 'categoria', 'Espécie ruminante de pequeno porte', 'corte e leite', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"cria","recria","engorda"}'::text[], 'recria', null, null, null, 'Muito menor que o do bovino, proporcional ao peso vivo. Definir com o cliente e com o nutricionista.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"sal mineral específico para ovinos","concentrado","proteinado"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","farelo-trigo","sal-mineral","nucleo-premix","caroco-algodao","casquinha-soja"}'::text[], '{"ATENÇÃO: ovinos são MUITO sensíveis ao COBRE. Mineral e núcleo de bovino podem intoxicar ovino. Produto tem que ser específico para a espécie.","Contaminação cruzada entre mineral de bovino e de ovino na mesma linha é risco real: exige limpeza e sequência de fabricação."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","A mesma máquina vai fazer mineral de bovino e de ovino?","O mineral que ele usa hoje é específico para ovinos?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca, igual ao bovino. O ponto crítico não é mecânico: é a SEQUÊNCIA DE FABRICAÇÃO, por causa do cobre.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM","BALANCA","ENSACADEIRA"}'::text[], 'Rebanho menor, mas quem produz ovino em escala compra concentrado o ano todo. O diferencial técnico da conversa é o cobre e a contaminação cruzada — poucos vendedores levantam isso.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'Ovino não é bovino pequeno: o cobre que faz bem pro boi pode matar a ovelha. Se o senhor vai fazer os dois na mesma máquina, a gente precisa combinar a ordem de produção e a limpeza.', 'Corte e leite, farelada seca. Ponto crítico: COBRE. Mineral de bovino intoxica ovino — sequência e limpeza importam.', 'Nordeste (forte), Sul (RS) e Centro-Oeste.', null, '🐑', 'em_revisao', true, '{"Espécie NOVA no guia: aguarda validação técnica e comercial para ficar visível ao vendedor.","Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-caprinos-ovinos"}'::text[], 'Auditoria 2026-08-03', null, null, null, 300),
  ('caprinos', 'Caprinos (corte e leite)', 'caprinos', 'Caprinocultura de corte e de leite. Muito ligada ao semiárido, onde convive com palma forrageira e com o concentrado que a complementa.', '{}'::text[], 'geral', 'categoria', 'Espécie ruminante de pequeno porte', 'corte e leite', '{"pasto","semiconfinamento","confinamento"}'::text[], '{"cria","recria","engorda"}'::text[], 'recria', null, null, null, 'Proporcional ao peso vivo, bem abaixo do bovino. Definir com o cliente e com o nutricionista.', 'kg de concentrado por animal por mês', '{"Peso vivo e fase","Genética","Qualidade do pasto ou do volumoso","Clima e conforto térmico","Sanidade do lote","Formulação e densidade da dieta"}'::text[], '{"sal mineral","concentrado","proteinado"}'::text[], '{"farelada"}'::text[], '{"milho","farelo-soja","farelo-trigo","sal-mineral","nucleo-premix","farelo-algodao","casquinha-soja"}'::text[], '{"Caprinos toleram cobre melhor que ovinos, mas o mineral ainda deve ser específico da espécie.","No semiárido a dieta costuma ter palma — que é ÚMIDA e NÃO entra na fábrica farelada."}'::text[], '{"Quantos animais tem no total?","Qual o peso médio do lote?","Qual o sistema — pasto, semiconfinamento ou confinamento?","É cria, recria ou engorda?","Quanto cada animal come por dia hoje?","Produz todo dia ou por batelada (uma vez por semana)?","Fornece sal comum, mineral, proteinado ou ração?","Quais ingredientes já tem na propriedade?","Trabalha com ingrediente úmido — silagem, caroço de algodão, palma?","Quantas horas por dia tem disponíveis para produzir?","A energia da propriedade é monofásica ou trifásica?","É caprino de leite ou de corte?","A dieta tem palma forrageira?","Ele quer produzir o CONCENTRADO que acompanha a palma?"}'::text[], '{"Cliente fala em \"sacos por mês\" mas não sabe o peso do saco","Não sabe o consumo por animal — só o gasto total em reais","Não sabe se a ração que compra é farelada ou peletizada","Não sabe quem formula a ração que usa hoje","Fala em \"fazer tudo\" sem separar concentrado de dieta com volumoso"}'::text[], 'Moagem + mistura seca do CONCENTRADO. No semiárido, a palma continua sendo fornecida à parte — a fábrica faz a proteína e o mineral que faltam nela.', '{"MOINHO","MISTURADOR","CACAMBA_PESAGEM","ENSACADEIRA"}'::text[], 'No semiárido a palma resolve energia e água, mas não resolve proteína. O concentrado que completa a palma é exatamente o que a fábrica produz.', '{"Não prometer ração PELETIZADA — a linha Branorte produz farelada.","Não prometer índice zootécnico (conversão, ganho de peso, litros, ovos): isso depende de genética, manejo, sanidade e formulação, não do equipamento.","Não afirmar que a fábrica \"resolve a nutrição\". Ela resolve a MISTURA; a fórmula é do nutricionista.","Não garantir economia sem rodar o estudo de viabilidade com os números do próprio cliente."}'::text[], '{"atende": ["Produção de ração FARELADA", "Milho e outros grãos triturados", "Mistura homogênea de ingredientes SECOS", "Pesagem, ensaque e transporte interno dos ingredientes"], "nao_atende": ["Peletização — a linha Branorte não peletiza", "Extrusão — não faz ração extrusada (peixe, pet)", "Ingredientes ÚMIDOS: silagem, palma, volumoso, cana picada", "Ingredientes LÍQUIDOS (óleo, melaço) sem sistema específico de dosagem", "Fibra LONGA: feno e capim enrolam no helicoide"], "ressalvas": ["Produtos minerais e sal são corrosivos: exigem rotina de limpeza", "Microingredientes (núcleo, aminoácido, ureia) exigem pré-mistura e balança precisa", "A Branorte fornece o equipamento; a formulação é de profissional habilitado"]}'::jsonb, 'A palma dá energia e água, mas falta proteína. A fábrica faz justamente esse concentrado que completa a palma — ela não processa a palma em si, que é molhada.', 'Corte e leite, forte no semiárido. A fábrica faz o CONCENTRADO que completa a palma (a palma é úmida e fica fora).', 'Nordeste/semiárido (forte) e Sudeste.', null, '🐐', 'em_revisao', true, '{"Espécie NOVA no guia: aguarda validação técnica e comercial para ficar visível ao vendedor.","Consumo é REFERÊNCIA de catálogo. Confirmar com o cliente antes de dimensionar."}'::text[], '{"embrapa-caprinos-ovinos","embrapa-semiarido"}'::text[], 'Auditoria 2026-08-03', null, null, null, 310)
